from pathlib import Path
import argparse,csv,html,json
p=argparse.ArgumentParser();p.add_argument('--records',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();d=json.loads(a.records.read_text());a.out.parent.mkdir(parents=True,exist_ok=True)
s=d['summary']; width=850; maxv=max([x['median_ns'] or 1 for x in s],default=1); colors={'baseline':'#4976a8','basis-reuse':'#d27b35'}; svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 310" role="img" aria-label="Median measured reducer duration by fixture and method"><style>text{font:14px sans-serif}.label{font-weight:bold}</style>']
for i,row in enumerate(s):
 y=35+i*43; v=row['median_ns'] or 0; xw=round(v/maxv*width); svg += [f'<text x="8" y="{y+15}">{html.escape(row["case_id"])} / {html.escape(row["method"])}</text>',f'<rect x="230" y="{y}" width="{xw}" height="22" fill="{colors.get(row["method"],"#777")}"/>',f'<text x="{240+xw}" y="{y+16}">{v/1e6:.3f} ms; n={row["successes"]}</text>']
svg.append('</svg>'); a.out.write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>OPT-06 basis-reuse results</title><style>body{font:16px system-ui;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#202a35}table{border-collapse:collapse;width:100%;margin:1rem 0}th,td{border:1px solid #ccd3da;padding:.45rem;text-align:left}th{background:#eef2f6}code{overflow-wrap:anywhere}.note{background:#f3f6f8;padding:1rem}svg{max-width:100%;height:auto}</style><h1>OPT-06: within-solve basis-reuse hull classification</h1><p>Descriptive Release measurements for one implementation and three small 2D fixtures. No speedup or general scaling claim is made.</p><div class="note"><b>Measured source commit:</b> <code>'+html.escape(d['code_commit'])+'</code><br><b>Evidence:</b> '+html.escape(d['process']['measured_rows'].__str__())+' measured rows, '+html.escape(d['process']['failures'].__str__())+' failed rows; report status remains descriptive because no separate limiter profile was collected.<br><b>Timing scope:</b> '+html.escape(d['environment']['timing_scope'])+'.</div><h2>Median durations</h2>'+''.join(svg)+'<h2>Per-method summary</h2><table><thead><tr>'+''.join('<th>'+html.escape({'median_lp_calls':'Membership LP calls (excludes Phase-I solve)','median_basis_solves':'Phase-I basis solves'}.get(k,k))+'</th>' for k in s[0].keys())+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(row[k]))+'</td>' for k in row)+'</tr>' for row in s)+'</tbody></table><h2>Evidence and limits</h2><p>'+html.escape(d['oracle'])+'</p><p>Hardware/compiler/build details and all raw rows are retained in <a href="records.json">records.json</a>, <a href="trials.csv">trials.csv</a>, <a href="summary.csv">summary.csv</a>, <a href="raw-stdout.jsonl">raw stdout JSONL</a>, <a href="raw-stderr.txt">raw stderr</a>, and the sanitized build log. LP/pivot/bulk counters describe operations, not elapsed-time components.</p><p>The fixtures are intentionally small and do not model the fuel-consumption application or establish production workload scaling. Timed methods are alternated, but no tuned performance verdict is drawn; a dedicated limiter profile and broader workload family would be needed before claiming a winner.</p></html>',encoding='utf-8')
